"""V5 — Visuels authentiques sélectionnés *pour chaque étape du récit*.

Aucun générateur d'images. Aucune recherche aléatoire. Toutes les photos candidates sont
préappariées à une anecdote et à un rôle dans photos_scenes.json. Le téléchargement
ne se fait qu'après contrôle de la licence sur Wikimedia Commons. Un aperçu actuel
n'est jamais présenté comme photographie d'époque.
"""
from __future__ import annotations
import datetime as dt
import hashlib, html, io, json, re
from pathlib import Path
from urllib.parse import urlparse
import requests
from PIL import Image, ImageOps, UnidentifiedImageError
from .catalogue import ROOT, STATE, read, write

API='https://commons.wikimedia.org/w/api.php'
UA='AnecdotesBD-verification/5.0 (images authentiques, license audit; GitHub public workflow)'
CATALOGUE=ROOT/'photos_scenes.json'
CACHE=STATE/'photos_authentiques'/'actifs_v5'
MAX_BYTES=12_000_000
MIN_PIXELS=340
BAD_SIGNS=re.compile(r'(midjourney|dall[ -]?e|stable diffusion|ai[ -]?generated|generated by ai|artificial intelligence generated|text.to.image|nightcafe|ideogram)',re.I)

class PhotosIndisponibles(RuntimeError):pass


def _meta_value(meta,key):
    return html.unescape(re.sub(r'<[^>]*>','',str((meta.get(key) or {}).get('value','')))).strip()


def _license(meta,titre,option):
    """Sans crédits publics : CC0 et certaines œuvres anciennes réellement PD.

    Le statut d'une page Commons ne transforme pas les photos modernes sous CC BY
    en images libres de toute attribution.
    """
    short=_meta_value(meta,'LicenseShortName').lower()
    combined=(_meta_value(meta,'UsageTerms')+' '+_meta_value(meta,'License')).lower()
    if BAD_SIGNS.search(titre+' '+_meta_value(meta,'ImageDescription')+' '+_meta_value(meta,'Artist')):
        raise PhotosIndisponibles('Média possiblement généré par IA : refus')
    if ('cc0' in short or 'cc-zero' in short or 'cc0' in combined):return 'CC0 1.0'
    if option.get('domaine_public_ancien') and option.get('artiste_mort_avant_1900'):
        if 'public domain' in short or 'domaine public' in short or 'pd-old' in short:
            return 'Domaine public historique : artiste décédé avant 1900'
    # Archives Outcault vérifiées : publication 1896, décès 1928 (LOC).
    # Liste fermée : ne généralise pas le statut des autres images Commons.
    archives_outcault={'1896-11-08 Yellow Kid.jpg','Yellow Kid 1896-3-15.jpg','Yellowkid phonograph.jpg','1896-11-15 Yellow Kid.jpg','Yellow Kid 1898-01-09.jpg','Yellow Kid November 1 1896 Bryan McKinley election.jpg','YellowKid.jpeg'}
    if (titre in archives_outcault and option.get('archive_outcault_1896')
            and 'outcault' in (_meta_value(meta,'Artist')+' '+_meta_value(meta,'ImageDescription')).lower()
            and ('public domain' in short or 'domaine public' in short or 'pd-old' in short)):
        return 'Domaine public : Richard F. Outcault (1863–1928), publication 1896–1898'
    # Corpus fermé de notices vérifiées, œuvres antérieures à 1931.
    # Aucune photo moderne ou licence CC BY n'est admise ici.
    archives_9e_art={"Mon Paris-Takarazuka1928.jpg":"Photographies anonymes publiées au Japon avant 1931, domaine public","Donburako-Takarazuka1914.jpg":"Photographies anonymes publiées au Japon avant 1931, domaine public","Paris Sette-Takarazuka1930.jpg":"Photographies anonymes publiées au Japon avant 1931, domaine public","Asaji Shinohara as Orihime (right), Kishiko Suminoe as Iserihime (left) in the Takarazuka Revue 'Yogo no Ten-nin' , 1920.jpg":"Photographies anonymes publiées au Japon avant 1931, domaine public","Upside-Downs of Little Lady Lovekins and Old Man Muffaroo (1904-12-18).gif":"Gustave Verbeek (1867–1937), planches parues en 1904","Ambigrams by Gustave Verbeek (1904) - comics The Upside Downs of Little Lady Lovekins and Old Man Muffaroo - The wonderful cure of the waterfall.jpg":"Gustave Verbeek (1867–1937), planches parues en 1904","Ambigrams by Gustave Verbeek (1904) - comics The Upside Downs of Little Lady Lovekins and Old Man Muffaroo - The bad snake and the good wizard.jpg":"Gustave Verbeek (1867–1937), planches parues en 1904","Verbeek-rocanoe.gif":"Gustave Verbeek (1867–1937), planches parues en 1904","Dream-of-the-Rarebit-Fiend-12-10-1904.jpg":"Winsor McCay (1869–1934), œuvres publiées avant 1931","Dream of the Rarebit Fiend 1905-02-25.jpg":"Winsor McCay (1869–1934), œuvres publiées avant 1931","Dream of the Rarebit Fiend 1905-01-07.jpg":"Winsor McCay (1869–1934), œuvres publiées avant 1931","Winsor McCay, Dream of the Rarebit Fiend - Here Comes Washington, 1908, NGA 142157.jpg":"Winsor McCay (1869–1934), œuvres publiées avant 1931","Dream of the Rarebit Fiend 1905-01-28 (cropped).jpg":"Winsor McCay (1869–1934), œuvres publiées avant 1931","Krazykat.jpg":"George Herriman (1880–1944), planches publiées avant 1931","Krazy Kat 1920-09-05 original.jpg":"George Herriman (1880–1944), planches publiées avant 1931","Krazy Kat 1921-11-20 original.jpg":"George Herriman (1880–1944), planches publiées avant 1931","Krazy Kat 1920-10-15 original.jpg":"George Herriman (1880–1944), planches publiées avant 1931","Krazy Kat 18 Dec 1919.jpg":"George Herriman (1880–1944), planches publiées avant 1931","Krazy Kat 1916-05-14.jpg":"George Herriman (1880–1944), planches publiées avant 1931","Hokusaimangapas.png":"Katsushika Hokusai (1760–1849), gravures du XIXe siècle","Hokusai Manga 01.jpg":"Katsushika Hokusai (1760–1849), gravures du XIXe siècle","Hokusaimanga vol1 okuzuke.jpg":"Katsushika Hokusai (1760–1849), gravures du XIXe siècle","Hokusai Mangá.jpg":"Katsushika Hokusai (1760–1849), gravures du XIXe siècle","Famille Cornouillet, future famille Fenouillard.JPEG":"Georges Colomb dit Christophe (1856–1945), œuvres publiées en 1889–1895","Famille Fenouillard.JPEG":"Georges Colomb dit Christophe (1856–1945), œuvres publiées en 1889–1895","Christophe - La Famille Fenouillard, 1895 (page 1 crop).jpg":"Georges Colomb dit Christophe (1856–1945), œuvres publiées en 1889–1895","Colomb - La Famille Fenouillard, 1895.jpg":"Georges Colomb dit Christophe (1856–1945), œuvres publiées en 1889–1895","Fenouillard 2.jpg":"Georges Colomb dit Christophe (1856–1945), œuvres publiées en 1889–1895","Histoire de la Sainte Russie LCCN2010645853.jpg":"Gustave Doré (1832–1883), ouvrage publié en 1854","Histoire pittoresque, dramatique et caricaturale de la Sainte Russie 1854 (142927547).jpg":"Gustave Doré (1832–1883), ouvrage publié en 1854","Histoire pittoresque, dramatique et caricaturale de la Sainte Russie 1854 (142927589).jpg":"Gustave Doré (1832–1883), ouvrage publié en 1854","Histoire pittoresque, dramatique et caricaturale de la Sainte Russie 1854 (142927599).jpg":"Gustave Doré (1832–1883), ouvrage publié en 1854","Histoire pittoresque, dramatique et caricaturale de la Sainte Russie 1854 (142927969).jpg":"Gustave Doré (1832–1883), ouvrage publié en 1854","Histoire pittoresque, dramatique et caricaturale de la Sainte Russie 1854 (142927527).jpg":"Gustave Doré (1832–1883), ouvrage publié en 1854","Histoire pittoresque, dramatique et caricaturale de la Sainte Russie 1854 (142927737).jpg":"Gustave Doré (1832–1883), ouvrage publié en 1854"}
    if (option.get('archive_9e_art') and titre in archives_9e_art and
            ('public domain' in short or 'domaine public' in short or 'pd-old' in short)
            and not any(x in short for x in ('cc by','cc-by','noncommercial','non-commercial'))):
        return 'Domaine public : '+archives_9e_art[titre]
    raise PhotosIndisponibles('Licence sans attribution publique non prouvée : '+short[:65])


def _valid_image_url(url):
    try:
        p=urlparse(str(url))
        return (p.scheme=='https' and not p.username and not p.password and p.port in (None,443) and (
            (p.hostname=='upload.wikimedia.org' and p.path.startswith('/wikipedia/commons/'))
            or (p.hostname=='thumb.wikimedia.org' and p.path.startswith('/wikipedia/commons/thumb/'))
            or (p.hostname=='commons.wikimedia.org' and (
                p.path.startswith('/wiki/Special:Redirect/file/')
                or p.path.startswith('/w/Special:Redirect/file/')))))
    except (TypeError,ValueError):return False


def _fetch_file(session,titre,option):
    if not re.fullmatch(r'[^<>\x00-\x1f]{6,210}\.(?:jpg|jpeg|png|webp|gif)',titre,re.I):
        raise PhotosIndisponibles('Nom de fichier non autorisé')
    params={'action':'query','format':'json','formatversion':'2','prop':'imageinfo',
      'iiprop':'url|mime|size|extmetadata','iiurlwidth':1600,'titles':'File:'+titre}
    r=session.get(API,params=params,timeout=20,headers={'User-Agent':UA})
    r.raise_for_status()
    pages=((r.json().get('query') or {}).get('pages') or [])
    if len(pages)!=1 or pages[0].get('missing') or not pages[0].get('imageinfo'):
        raise PhotosIndisponibles('Fichier absent sur Commons')
    inf=pages[0]['imageinfo'][0]
    if inf.get('mime') not in ('image/jpeg','image/png','image/webp','image/gif'):
        raise PhotosIndisponibles('Type de média non pris en charge')
    # La notice Commons du phonographe n'a pas de champ auteur lisible
    # par machine. L'original vérifié est identifié par son SHA-1 publié.
    # Aucun autre fichier ne bénéficie de cette voie.
    pinned=(titre=='Yellowkid phonograph.jpg' and option.get('archive_outcault_1896'))
    if pinned:
        licence='Domaine public : Richard Outcault (1863–1928), 25 octobre 1896'
        urls=['https://upload.wikimedia.org/wikipedia/commons/9/9b/Yellowkid_phonograph.jpg']
    else:
        licence=_license(inf.get('extmetadata') or {},titre,option)
        urls=[inf.get('thumburl',''),inf.get('url','')]
    url=next((u for u in urls if _valid_image_url(u)),None)
    if not url:
        raise PhotosIndisponibles('URL Commons non reconnue : '+', '.join(str(urlparse(u).hostname) for u in urls)[:80])
    response=session.get(url,timeout=26,headers={'User-Agent':UA},stream=True)
    try:
        response.raise_for_status()
        if not _valid_image_url(response.url):raise PhotosIndisponibles('Redirection média hors de Commons')
        if not response.headers.get('Content-Type','').lower().startswith('image/'):
            raise PhotosIndisponibles('Le contenu distant ne semble pas être une image')
        buffers=[];size=0
        for b in response.iter_content(65536):
            size+=len(b)
            if size>MAX_BYTES:raise PhotosIndisponibles('Photo trop lourde')
            buffers.append(b)
        data=b''.join(buffers)
    finally:response.close()
    if pinned and hashlib.sha1(data).hexdigest()!='50fd735bca545fe0db6416d3139b10e1f066b854':
        raise PhotosIndisponibles('Empreinte de l’archive Outcault différente de la notice')
    if len(data)<8500:raise PhotosIndisponibles('Média trop petit ou non téléchargé')
    with Image.open(io.BytesIO(data)) as src:
        if (src.width<MIN_PIXELS or src.height<MIN_PIXELS or
            src.width*src.height>55_000_000):
            raise PhotosIndisponibles('Résolution insuffisante/excessive')
        im=ImageOps.exif_transpose(src).convert('RGB')
        im.thumbnail((1800,1800),Image.Resampling.LANCZOS)
        out=io.BytesIO();im.save(out,'JPEG',quality=88,optimize=True)
    blob=out.getvalue();metadata=inf.get('extmetadata') or {}
    return blob,{'titre_commons':titre,
      'url_commons':'https://commons.wikimedia.org/wiki/File:'+titre.replace(' ','_'),
      'image_url':url,'licence':licence,'auteur':('Richard F. Outcault (1863–1928)' if pinned else _meta_value(metadata,'Artist')[:300]),
      'description':('Yellow Kid, 25 octobre 1896, notice Commons et SHA-1 vérifiés' if pinned else _meta_value(metadata,'ImageDescription')[:400]),
      'sha256':hashlib.sha256(blob).hexdigest(),
      'date_collecte':dt.datetime.now(dt.timezone.utc).isoformat(),
      'illustration_IA':False}


def _phash(path):
    # Signature perceptuelle : 2 encodages d'un même cliché ne comptent pas pour deux.
    from .visuels import _photo_hash
    with Image.open(path) as img:return _photo_hash(img)


def _maximise_diversite(files,proofs):
    """Préserve l'ordre narratif, élimine doublons de contenu / famille originale."""
    if len(files)!=len(proofs):raise ValueError('Chaque photo doit conserver sa preuve')
    used_hashes=[];used_origins=set();selected=[];evidence=[]
    for path,record in zip(files,proofs):
        ph=_phash(path)
        origin=record.get('famille_source') or record.get('titre_commons')
        if origin in used_origins:continue
        if any((ph^h).bit_count()<=4 for h in used_hashes):continue
        selected.append(path);evidence.append(record)
        used_hashes.append(ph);used_origins.add(origin)
    return selected,evidence


def resolve(fact,*,session=None,cache=None):
    """Retourne (paths, preuves) : 3+ scènes pertinentes, uniques et sous licence admissible.

    Une photo *d'ambiance* n'est pas un substitut à la scène prévue : aucun repli
    automatique sur une série au hasard si une photo manque.
    """
    session=session or requests.Session();cache=Path(cache or CACHE)
    book=read(CATALOGUE,{}) or {}
    scen=(book.get('scenarios') or {}).get(fact['id'])
    if not scen:
        raise PhotosIndisponibles('Aucun scénario illustré vérifié pour '+fact['id']+' (ne pas utiliser de photo générique)')
    options=sorted(scen.get('visuels') or [],key=lambda d:d['page'])
    min_required=int(book.get('minimum_images_distinctes',3))
    if not (2<=min_required<=5):raise ValueError('Configuration d’images invalide')
    if len({op.get('page') for op in options})!=len(options):
        raise ValueError('Plusieurs photos affectées à une même étape')
    cache.mkdir(parents=True,exist_ok=True)
    choices=[];proofs=[];errors=[]
    used_hashes=[];used_origins=set()
    for op in options:
        alternatives=[op,*op.get('alternatives',[])]
        chosen=False
        for alt in alternatives:
            # Une alternative reste attachée au même passage et doit conserver
            # un rôle narratif et une justification éditoriale explicites.
            candidate={**op,**alt}
            titre=candidate['titre']
            if not candidate.get('pertinence') or not candidate.get('role'):
                errors.append('page '+str(op['page'])+': image sans pertinence éditoriale')
                continue
            key=hashlib.sha256(titre.encode('utf8')).hexdigest()[:22]
            dest=cache/(key+'.jpg');meta_path=cache/(key+'.json')
            try:
                if dest.exists() and meta_path.exists():
                    meta=read(meta_path,{})
                    if not (meta.get('titre_commons')==titre and meta.get('licence') and
                           meta.get('sha256')==hashlib.sha256(dest.read_bytes()).hexdigest()):
                        raise PhotosIndisponibles('Cache photo sans preuve intacte')
                else:
                    blob,meta=_fetch_file(session,titre,candidate)
                    dest.write_bytes(blob);write(meta_path,meta)
                family=candidate.get('famille_source') or titre
                fingerprint=_phash(dest)
                if family in used_origins or any((fingerprint^h).bit_count()<=4 for h in used_hashes):
                    errors.append('page '+str(op['page'])+': photographie déjà utilisée, autre variante essayée')
                    continue
                proof={**meta,
                    'page':op['page'],'role':candidate['role'],
                    'pertinence':candidate['pertinence'],
                    'epoque':candidate.get('epoque','actuelle'),
                    'famille_source':family,'fact_id':fact['id'],
                    'intention_editoriale':scen['intention']}
                choices.append(dest);proofs.append(proof)
                used_hashes.append(fingerprint);used_origins.add(family)
                chosen=True
                break
            except (PhotosIndisponibles,requests.RequestException,UnidentifiedImageError,OSError,ValueError,KeyError) as exc:
                errors.append(f'page {op.get("page")}: {titre} — {type(exc).__name__} {str(exc)[:95]}')
        if not chosen:
            errors.append('page '+str(op['page'])+': aucune alternative pertinente disponible')
    if len(choices)<min_required or not any(p['page']==1 for p in proofs):
        raise PhotosIndisponibles(
            f'Photos narratives insuffisantes pour {fact["id"]}: {len(choices)}/{min_required} '
            'photographies réellement différentes avec lien à la scène. '
            +' ; '.join(errors)[:450])
    if len(set(p['page'] for p in proofs))!=len(proofs):
        raise PhotosIndisponibles('Scènes photographiques non distinctes')
    return choices,proofs
